import{_ as i,o as t,c as o,a0 as a}from"./chunks/framework.CWG7uS0z.js";const g=JSON.parse('{"title":"后端设计 (Spring Boot 3)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/backend.md","filePath":"guide/backend.md"}'),s={name:"guide/backend.md"};function n(r,e,l,d,c,p){return t(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="后端设计-spring-boot-3" tabindex="-1">后端设计 (Spring Boot 3) <a class="header-anchor" href="#后端设计-spring-boot-3" aria-label="Permalink to &quot;后端设计 (Spring Boot 3)&quot;">​</a></h1><p>后端系统是 Farmer Platform 的心脏，位于 <code>backend/farmer_platform</code> 目录。它基于 Java 21 和 Spring Boot 3 构建，遵循领域驱动设计 (DDD) 的部分理念，提供稳定、安全、可分页的 RESTful API。</p><h2 id="_1-核心技术选型" tabindex="-1">1. 核心技术选型 <a class="header-anchor" href="#_1-核心技术选型" aria-label="Permalink to &quot;1. 核心技术选型&quot;">​</a></h2><ul><li><strong>运行环境</strong>: Java 21 LTS</li><li><strong>核心框架</strong>: Spring Boot 3.2+</li><li><strong>持久层</strong>: Spring Data JPA / Hibernate</li><li><strong>数据库</strong>: MySQL 8.x</li><li><strong>安全认证</strong>: JJWT (Java JWT)</li><li><strong>工程提效</strong>: Lombok (减少 Getter/Setter 样板代码)</li></ul><h2 id="_2-目录架构与分层-layered-architecture" tabindex="-1">2. 目录架构与分层 (Layered Architecture) <a class="header-anchor" href="#_2-目录架构与分层-layered-architecture" aria-label="Permalink to &quot;2. 目录架构与分层 (Layered Architecture)&quot;">​</a></h2><p>代码严格按照标准的三层架构（Controller -&gt; Service -&gt; Repository）进行组织：</p><ul><li><strong><code>config</code></strong>: 存放 Spring 的配置类，例如 CORS 跨域配置 (<code>WebConfig.java</code>)。</li><li><strong><code>controller</code></strong>: 负责暴露 REST API 路由，接收前端请求并校验基本参数，然后转发给 Service 层。</li><li><strong><code>service</code></strong>: 封装所有的核心业务逻辑（如生成订单、计算总价、密码比对）。</li><li><strong><code>repository</code></strong>: 继承 <code>JpaRepository</code>，负责与 MySQL 数据库交互，执行 CRUD 和动态查询。</li><li><strong><code>entity</code></strong>: JPA 实体类，通过 <code>@Entity</code> 和 <code>@Table</code> 注解直接映射到数据库表。</li><li><strong><code>dto</code> (Data Transfer Object)</strong>: 用于在 Controller 和前端之间传输数据。例如 <code>LoginRequest</code>, <code>ProductResponse</code>。DTO 严格隔离了数据库实体结构与对外暴露的数据结构。</li><li><strong><code>common</code></strong>: 存放全局通用的工具类与统一包装对象，如 <code>ApiResponse&lt;T&gt;</code> 和 <code>PagedResponse&lt;T&gt;</code>。</li><li><strong><code>security</code></strong>: 存放自定义的 <code>AuthInterceptor</code> 和 JWT 生成/解析工具。</li></ul><h2 id="_3-安全架构-jwt-security" tabindex="-1">3. 安全架构 (JWT Security) <a class="header-anchor" href="#_3-安全架构-jwt-security" aria-label="Permalink to &quot;3. 安全架构 (JWT Security)&quot;">​</a></h2><p>我们没有引入沉重的 Spring Security，而是实现了一个轻量级、高可控的 <code>AuthInterceptor</code>。</p><h3 id="_3-1-鉴权流程" tabindex="-1">3.1 鉴权流程 <a class="header-anchor" href="#_3-1-鉴权流程" aria-label="Permalink to &quot;3.1 鉴权流程&quot;">​</a></h3><ol><li>用户调用 <code>/api/auth/login</code> 接口，传入账号密码。</li><li><code>AuthService</code> 验证通过后，调用 <code>JwtService</code> 生成一个签名的 Token，并返回给前端。</li><li>前端在后续请求的 HTTP Header 中附带 <code>Authorization: Bearer &lt;token&gt;</code>。</li><li><strong><code>AuthInterceptor</code></strong> 在请求到达具体 Controller 之前进行拦截： <ul><li>提取 Header 中的 Token。</li><li>验证 Token 的签名与有效期。</li><li>如果验证失败，抛出 401 未授权异常，由全局异常处理器接管。</li></ul></li></ol><h3 id="_3-2-跨域与-options-预检" tabindex="-1">3.2 跨域与 OPTIONS 预检 <a class="header-anchor" href="#_3-2-跨域与-options-预检" aria-label="Permalink to &quot;3.2 跨域与 OPTIONS 预检&quot;">​</a></h3><p><code>AuthInterceptor</code> 针对浏览器的 CORS 机制进行了专门适配，<strong>强制无条件放行 <code>OPTIONS</code> 请求</strong>，避免前端的预检请求被误杀为 401。</p><h2 id="_4-分页第一原则-pagination-first" tabindex="-1">4. 分页第一原则 (Pagination First) <a class="header-anchor" href="#_4-分页第一原则-pagination-first" aria-label="Permalink to &quot;4. 分页第一原则 (Pagination First)&quot;">​</a></h2><p>在后端开发中，所有的列表查询接口<strong>必须</strong>实现分页。这保证了在面对成千上万条农产品或订单数据时，服务器内存与网络带宽不会被撑爆。</p><p><strong>实现方式</strong>:</p><ol><li>Controller 接收前端传来的 <code>page</code> (当前页码，默认 0) 和 <code>size</code> (每页条数，默认 10)。</li><li>构建 <code>PageRequest.of(page, size)</code>。</li><li>调用 Repository 继承的基于 <code>Pageable</code> 的查询方法。</li><li>将查询结果 (包含数据列表、总页数、总条数) 封装为 <code>PagedResponse&lt;T&gt;</code> 并由 <code>ApiResponse</code> 包裹返回。</li></ol><h2 id="_5-api-统一响应规范" tabindex="-1">5. API 统一响应规范 <a class="header-anchor" href="#_5-api-统一响应规范" aria-label="Permalink to &quot;5. API 统一响应规范&quot;">​</a></h2><p>为了让前端能够有一致的处理逻辑，后端抛弃了随意的返回格式，所有的接口必须返回标准的 <code>ApiResponse</code>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 业务状态码 (200: 成功, 401: 未授权, 400: 业务异常, 500: 服务器错误)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;操作成功&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 提示信息</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 具体的业务数据结构</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div>`,20)])])}const k=i(s,[["render",n]]);export{g as __pageData,k as default};
